<?php require_once __DIR__.'/../bootstrap.php';require_admin();$page=valid_page();$per=25;$q=trim($_GET['q']??'');$active=$_GET['active']??'';$where=[];$p=[];if($q!==''){$where[]='(name LIKE ? OR email LIKE ?)';$p[]="%$q%";$p[]="%$q%";}if($active!==''){$where[]='active=?';$p[]=(int)$active;}$w=$where?' WHERE '.implode(' AND ',$where):'';$c=$pdo->prepare("SELECT COUNT(*) FROM users$w");$c->execute($p);$pages=max(1,ceil($c->fetchColumn()/$per));$s=$pdo->prepare("SELECT id,name,email,is_admin,active,created_at FROM users$w ORDER BY id DESC LIMIT ? OFFSET ?");foreach($p as $i=>$v)$s->bindValue($i+1,$v);$s->bindValue(count($p)+1,$per,PDO::PARAM_INT);$s->bindValue(count($p)+2,($page-1)*$per,PDO::PARAM_INT);$s->execute();$title='Users — AniRead';include __DIR__.'/../includes/header.php';?><h1>Users</h1><form class="filters"><input class="input" name="q" value="<?=e($q)?>" placeholder="Name or email"><select name="active"><option value="">All</option><option value="1" <?=selected($active,'1')?>>Active</option><option value="0" <?=selected($active,'0')?>>Disabled</option></select><button class="btn">Filter</button></form><table class="table"><tr><th>Name</th><th>Email</th><th>Admin</th><th>Active</th></tr><?php foreach($s as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=$u['is_admin']?'Yes':'No'?></td><td><?=$u['active']?'Yes':'No'?></td></tr><?php endforeach;?></table><?php page_links($page,$pages,'users.php?q='.rawurlencode($q).'&active='.rawurlencode($active));include __DIR__.'/../includes/footer.php';
